# Generated by build.py from recipe.yml for recipe smtp-answer-try-later. Do not edit.
Set-Location $PSScriptRoot
[IO.File]::WriteAllText((Join-Path $PWD 'order.eml'), "From: app@example.com`r`nTo: ann@example.com`r`nSubject: Order 1042 has shipped`r`n`r`nYour order is on its way.`r`n")
$server0 = Start-Process surl -ArgumentList '-v', '--log-file', 'surl.log', '--mail-domain', 'example.com', '--mailbox', 'app@example.com:apppass', '--mailbox', 'ann@example.com:annpass', '--fault', '"error;scheme=smtp;command=RCPT;reply=451', '4.3.0', 'try', 'later;times=1"', 'smtp://127.0.0.1:8080/', 'imap://127.0.0.1:8081/' -PassThru -NoNewWindow
Start-Sleep 1
try { curl.exe -s --crlf -u app@example.com:apppass --mail-from app@example.com --mail-rcpt ann@example.com -T order.eml -w "%{response_code}\n" "smtp://127.0.0.1:8080/{first,second}" } finally { Stop-Process $server0 }
